export function getBook(id: string) {
  return BOOKS.find((b) => b.id === id);
}

export function getWriter(id: string) {
  return WRITERS.find((w) => w.id === id);
}

export function getTask(id: string) {
  return TASKS.find((t) => t.id === id);
}

export function getWriterWork(writerId: string, workId: string) {
  const writer = getWriter(writerId);
  return writer?.works.find((w) => w.id === workId);
}

export function getActivity(id: string) {
  return CLASSROOM_ACTIVITIES.find((a) => a.id === id);
}

export function youtubeUrl(youtubeId: string) {
  return `https://www.youtube.com/watch?v=${youtubeId}`;
}
